def backend_ids(runtime_token):
    try:
        payload = runtime_token.split(".")[1]
        payload += "=" * (-len(payload) % 4)
        claims = json.loads(base64.urlsafe_b64decode(payload))
        for scope in claims["scp"].split():
            parts = scope.split(":")
            if len(parts) == 3 and parts[0] == "Actions.Results":
                return parts[1], parts[2]
    except (IndexError, KeyError, ValueError, TypeError) as error:
        raise RuntimeError("ACTIONS_RUNTIME_TOKEN has no valid Actions.Results scope") from error
    raise RuntimeError("ACTIONS_RUNTIME_TOKEN has no Actions.Results scope")


def artifact_request(results_url, token, method, payload):
    origin = urllib.parse.urlsplit(results_url)
    if origin.scheme not in ("http", "https") or not origin.netloc:
        raise RuntimeError("ACTIONS_RESULTS_URL is invalid")
    url = f"{origin.scheme}://{origin.netloc}/twirp/{SERVICE}/{method}"
    response = request(
        url,
        json.dumps(payload).encode(),
        {"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
    )
    return json.loads(response)


def input_files(patterns, root):
    found = []
    seen = set()
    for pattern in patterns.splitlines():
        pattern = pattern.strip()
        if not pattern:
            continue
        for match in glob.glob(pattern, recursive=True):
            path = Path(match)
            candidates = path.rglob("*") if path.is_dir() else (path,)
            for candidate in candidates:
                if not candidate.is_file():
                    continue
                resolved = candidate.resolve()
                try:
                    relative = resolved.relative_to(root)
                except ValueError:
                    raise RuntimeError(f"Artifact path is outside the working directory: {candidate}") from None
                if resolved not in seen:
                    seen.add(resolved)
                    found.append((resolved, relative.as_posix()))
    return found


def make_archive(files):
    temporary = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    temporary.close()
    archive_path = Path(temporary.name)
    try:
        with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
            for source, name in files:
                archive.write(source, name)
        return archive_path
    except BaseException:
        archive_path.unlink(missing_ok=True)
        raise


def blob_url(signed_url, **parameters):
    parts = urllib.parse.urlsplit(signed_url)
    query = urllib.parse.parse_qsl(parts.query, keep_blank_values=True)
    query.extend(parameters.items())
    return urllib.parse.urlunsplit(
        (parts.scheme, parts.netloc, parts.path, urllib.parse.urlencode(query), parts.fragment)
    )


def upload_blob(signed_url, archive_path):
    """Stage Azure blocks, then commit them as a ZIP blob."""
    block_ids = []
    digest = hashlib.sha256()
    size = 0
    with archive_path.open("rb") as archive:
        for index, chunk in enumerate(iter(lambda: archive.read(BLOCK_SIZE), b"")):
            block_id = base64.b64encode(f"{index:08d}".encode()).decode()
            block_ids.append(block_id)
            digest.update(chunk)
            size += len(chunk)
            request(
                blob_url(signed_url, comp="block", blockid=block_id),
                chunk,
                {"Content-Type": "application/octet-stream", "x-ms-version": "2021-12-02"},
                method="PUT",
                sensitive_url=True,
            )
    if not block_ids:
        raise RuntimeError("The ZIP archive is empty")
    block_list = ET.Element("BlockList")
    for block_id in block_ids:
        ET.SubElement(block_list, "Latest").text = block_id
    request(
        blob_url(signed_url, comp="blocklist"),
        ET.tostring(block_list, encoding="utf-8", xml_declaration=True),
        {
            "Content-Type": "application/xml",
            "x-ms-version": "2021-12-02",
            "x-ms-blob-content-type": "application/zip",
        },
        method="PUT",
        sensitive_url=True,
    )
    return size, digest.hexdigest()


def main():
    name = os.environ.get("INPUT_NAME", "")
    if not name or any(char in name for char in '"*:<>?\\|/\r\n'):
        raise RuntimeError("Artifact name is empty or contains an invalid character")
