    files = input_files(os.environ.get("INPUT_PATH", ""), root)
    if not files:
        print(f"No files to upload for {name}")
        return

    token = os.environ.get("ACTIONS_RUNTIME_TOKEN")
    results_url = os.environ.get("ACTIONS_RESULTS_URL")
